    inspectCost(){return L.inspectCost(this.s.run);}
    acknowledgeLaw(){return this.transaction(()=>{const r=this.s.run;if(!r||!this.law())return;if(!r.lawSeenDepths.includes(r.depth)){r.lawSeenDepths.push(r.depth);this.record('law-acknowledged',{law:r.map.lawId});}});}
    signs(){return X.signs(this.s.run);}
    currentEncounter(){const r=this.s.run;if(r?.battleEvent){const e=X.eventAt(r.map,r.nodeId);return e&&e.id===r.battleEvent?{patterns:[e.type==='broadcast'?'pursuer':'hunter'],mandatory:false,cleared:e.status==='resolved'}:null;}return this.node()?.encounter;}
    transaction(fn){const old=this.snapshot();try{const result=fn();this.assert();return result;}catch(e){this.s=old;throw e;}}
