        if(defeated&&r.battleEvent)X.eventAt(r.map,r.nodeId).status='failed';if(defeated)return this.settle('FAILED',r.config.failurePolicy==='any-downed'?'전투에서 동료 전투불능':'전투에서 전원 전투불능');
        if(r.battleEvent)X.eventAt(r.map,r.nodeId).status='resolved';else this.node().encounter.cleared=true;r.gold+=8+r.depth*5+(this.currentEncounter()?.mandatory?8:0);this.record('combat-won',{rounds:b.s.round});r.battle=null;r.battleNode=null;r.battleEvent=null;r.offers=this.rewards();r.phase='REWARD';
